head.script:
// 수정사유

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function() {
    try {
        $c.cm.PanelToGroupBox(panel_2);
        txb_DEL_RSN.focus();
        txb_flag.setValue("한글종목명");
        txb_code.setValue("표준코드");
        txb_ISU_NM.setValue($c.frame.path("../").txb_ISU_NM.getValue());
        txb_KEYVALUE.setValue($c.frame.path("../").txb_STD_CD.getValue());
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDBNS22003.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_close_onclick
 * @description 「닫기」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_close_onclick = async function() {
    try {
        await $c.win.closePopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS22003.btn_close_onclick" });
    }
};

/**
 * @method
 * @name btn_confirm_onclick
 * @description 「수정」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_confirm_onclick = async function() {
    try {
        if (txb_DEL_RSN.getValue() === "" || txb_DEL_RSN.getValue().indexOf(" ") === "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-A005", "사유"));
            txb_DEL_RSN.focus();
            return;
        }
        if (!$c.stf.checkMaxLength(txb_DEL_RSN, 40, "사유")) {
            // txb_DEL_RSN.value = "";
            txb_DEL_RSN.focus();
            return false;
        }

        // var rtn = confirm('삭제 하시겠습니까?')
        // if (rtn == 1) // [삭제] 버튼이 눌려졌을 경우
        // {
        await scwin.ins_register();
        // }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDBNS22003.btn_confirm_onclick" });
    }
};

/**
 * @method
 * @name txb_DEL_RSN_onkeyup
 * @description txb_DEL_RSN 키 입력 이벤트
 * @returns {void}
 * @hidden N
 */
scwin.txb_DEL_RSN_onkeyup = function() {
    // fn_DelChar(this);

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name ins_register
 * @description 수정사유 등록
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.ins_register = async function() {
    // frame.Provider("../").ins_popupRtn_cdnm(txb_DEL_RSN.value,"");
    // txb_DEL_RSN
    $c.frame.path("../").fn_Save_Info(txb_DEL_RSN.getValue()); // ESG채권관리(BNS22000) 수정버튼 처리
    await $c.win.closePopup();
};
